\begin{lemma}\label{lem:added-2}
If and only if
\begin{equation}
C\geq0 \quad \text{or}\quad C<-\frac{1}{39},
\end{equation}
we have
\begin{equation}
{\textnormal{Re}}(z)>0,
\end{equation}
i.e., all roots of the equation \eqref{equation_C}  lie in the right half-plane,
in another words, the amplification factor $G(z)$ is analytic in $\textnormal{Re}(z)\leq 0$. 
\end{lemma}
